changeSet.sql:
if exists(select * from INFORMATION_SCHEMA.TABLES where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Setting')
begin 
	exec sp_rename 'dbo.Setting', 'Setting_backup';
end

if exists(select * from INFORMATION_SCHEMA.TABLES where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'CompanySetting')
begin 
	exec sp_rename 'dbo.CompanySetting', 'CompanySetting_backup';
end
